changeSet.sql:
ALTER TABLE payment_tranches DROP COLUMN IF EXISTS amount_gross;
ALTER TABLE payment_tranches DROP COLUMN IF EXISTS paid_gross;
ALTER TABLE payment_tranches DROP COLUMN IF EXISTS due_date;
ALTER TABLE payment_tranches DROP COLUMN IF EXISTS status;

rollback.sql:
ALTER TABLE payment_tranches ADD COLUMN IF NOT EXISTS amount_gross NUMERIC(14,2);
ALTER TABLE payment_tranches ADD COLUMN IF NOT EXISTS paid_gross NUMERIC(14,2);
ALTER TABLE payment_tranches ADD COLUMN IF NOT EXISTS due_date DATE;
ALTER TABLE payment_tranches ADD COLUMN IF NOT EXISTS status VARCHAR(24);
UPDATE payment_tranches t
   SET amount_gross = cp.amount_gross, paid_gross = cp.paid_gross,
       due_date = cp.due_date, status = cp.status
  FROM client_payments cp WHERE cp.id = t.client_payment_id;

changeSet.sql:
ALTER TABLE client_proformas DROP COLUMN IF EXISTS status;
ALTER TABLE client_proformas DROP COLUMN IF EXISTS due_date;
ALTER TABLE client_proformas DROP COLUMN IF EXISTS total_gross;
ALTER TABLE client_proformas DROP COLUMN IF EXISTS paid_gross;
ALTER TABLE client_proformas DROP COLUMN IF EXISTS currency;
ALTER TABLE client_proformas DROP COLUMN IF EXISTS note;

rollback.sql:
ALTER TABLE client_proformas ADD COLUMN IF NOT EXISTS status VARCHAR(24);
ALTER TABLE client_proformas ADD COLUMN IF NOT EXISTS due_date DATE;
ALTER TABLE client_proformas ADD COLUMN IF NOT EXISTS total_gross NUMERIC(14,2);
ALTER TABLE client_proformas ADD COLUMN IF NOT EXISTS paid_gross NUMERIC(14,2);
ALTER TABLE client_proformas ADD COLUMN IF NOT EXISTS currency VARCHAR(3);
ALTER TABLE client_proformas ADD COLUMN IF NOT EXISTS note VARCHAR(1000);
UPDATE client_proformas p
   SET status = cp.status, due_date = cp.due_date, total_gross = cp.amount_gross,
       paid_gross = cp.paid_gross, currency = cp.currency, note = cp.note
  FROM client_payments cp WHERE cp.id = p.client_payment_id;
